export function candidateSources(source: string): [string, string][] {
  const cutoff = 'if (transmittance < 0.01) break;'
  const start = source.indexOf('    for (int i = 0; i < 256; i++) {')
  const end = source.indexOf('    if (positionWeight > 1e-8)', start)
  if (start < 0 || end < 0 || !source.includes(cutoff)) throw new Error('Missing view-march markers')
  const loop = source.slice(start, end)
  const bound = '(max(uDensityScale * uGasAbsorption, 0.0) + max(uDustStrength, 0.0)) * (tf - tn)'
  const condition = `uDensityUnitRange > 0.5 && ${bound} < 4.0`
  const guarded = source.replace(cutoff, `if (!(${condition}) && transmittance < 0.01) break;`)
  const split = source.slice(0, start) + `    if (${condition}) {\n${loop.replace(cutoff, '')}    } else {\n${loop}    }\n` + source.slice(end)
  return [
    ['noViewCutoffDiagnostic', source.replace(cutoff, '')],
    ['guardedViewCutoff', guarded],
    ['boundedViewSplit', split]
  ]
}

import { Color, FloatType, GLSL3, Mesh, NoBlending, OrthographicCamera, PlaneGeometry, ShaderMaterial, UniformsUtils, WebGLRenderTarget } from 'three'
import { getInitializedSimulationRuntime } from '/src/ui/runtime/simulationRuntime'
import { Tokens } from '/src/core/providers/tokens'
import { GpuTimer } from '/tests/browser/gpuTimer'
import { state } from './profile.browser'
import { candidateSources } from './nebula-view-bound-variants-2026-10-27'

const stats = (values: number[]) => { const sorted = values.slice().sort((a,b)=>a-b); return {count:values.length,p50:sorted[15],p95:sorted[30],max:sorted[31]} }
const owner = (object: any, id: number) => { for(;object;object=object.parent)if(object.model?.getAttribute('id')===id)return true;return false }
export async function diagnose(actorId: number) {
  const c=getInitializedSimulationRuntime()!.container,engine:any=c.get(Tokens.Engine),renderer=c.get(Tokens.Renderer)
  const volume:any=c.get(Tokens.DepthVolumeRegistry).volumes().find(v=>owner(v,actorId))
  if(!volume)throw new Error('Main nebula absent')
  engine.stop()
  const gl=renderer.getContext() as WebGL2RenderingContext,draw=renderer.render
  const savedTarget=renderer.getRenderTarget(),savedAuto=renderer.autoClear,savedAlpha=renderer.getClearAlpha(),savedColor=renderer.getClearColor(new Color())
  const targets:WebGLRenderTarget[]=[],materials:ShaderMaterial[]=[]
  const copyMaterial=new ShaderMaterial({glslVersion:GLSL3,uniforms:{map:{value:null}},depthTest:false,depthWrite:false,blending:NoBlending,
    vertexShader:'void main(){gl_Position=vec4(position.xy,0.0,1.0);}',
    fragmentShader:'uniform sampler2D map;out vec4 color;void main(){color=texelFetch(map,ivec2(gl_FragCoord.xy),0);}'})
  const copyMesh=new Mesh(new PlaneGeometry(2,2),copyMaterial),copyCamera=new OrthographicCamera()
  let uniforms:any,mesh:Mesh,camera:any,source='',defines:any,width=0,height=0,actualTarget:any
  const read=(target:WebGLRenderTarget,index=0)=>{
    const pixels=new Float32Array(target.width*target.height*4)
    renderer.readRenderTargetPixels(target,0,0,target.width,target.height,pixels,undefined,index)
    if(pixels.some(v=>!Number.isFinite(v)))throw new Error('Nonfinite diagnostic image')
    return pixels
  }
  try{
    renderer.render=function(object:any,view:any){
      draw.call(this,object,view)
      if(object!==volume||uniforms||object.material.uniforms.uLowResolutionEnabled.value!==0)return
      const out=renderer.getRenderTarget()
      if(!out||out.texture.name!=='DepthVolume reduced HDR')return
      source=object.material.fragmentShader;defines={...object.material.defines};uniforms={}
      for(const [name,u]of Object.entries(object.material.uniforms)as any)uniforms[name]=u.value?.isTexture?{value:u.value}:UniformsUtils.clone({u}).u
      const depth=uniforms.uSceneDepth.value,copy=new WebGLRenderTarget(depth.image.width,depth.image.height,{type:FloatType,depthBuffer:false,minFilter:depth.minFilter,magFilter:depth.magFilter})
      targets.push(copy);renderer.setRenderTarget(copy);copyMaterial.uniforms.map.value=depth;draw.call(renderer,copyMesh,copyCamera);renderer.setRenderTarget(out)
      uniforms.uSceneDepth.value=copy.texture
      width=uniforms.uResolution.value.x;height=uniforms.uResolution.value.y
      actualTarget={width:out.width,height:out.height,type:out.texture.type,count:out.textures.length,viewport:out.viewport.toArray()}
      camera=view.clone();mesh=new Mesh(object.geometry,copyMaterial);mesh.layers.mask=object.layers.mask;mesh.matrixAutoUpdate=false
      mesh.matrix.copy(object.matrixWorld);mesh.updateMatrixWorld(true);mesh.frustumCulled=false
    }
    engine.renderFrame();renderer.render=draw;renderer.autoClear=false
    if(!uniforms||!('NEB_BAKED_ONLY'in defines)||width!==640||height!==360)throw new Error('Missing actual reduced baked nebula draw')
    const snapshot=state(),output=new WebGLRenderTarget(width,height,{count:2,type:FloatType,depthBuffer:false});targets.push(output)
    const make=(fragmentShader:string)=>{
      const m=new ShaderMaterial({glslVersion:volume.material.glslVersion,vertexShader:volume.material.vertexShader,fragmentShader,uniforms,defines,side:volume.material.side,depthTest:false,depthWrite:false,blending:NoBlending})
      materials.push(m);return m
    }
    const render=(material:ShaderMaterial)=>{renderer.setRenderTarget(output);renderer.setClearColor(0,0);renderer.clear(true,false,false);mesh.material=material;draw.call(renderer,mesh,camera)}
    const measure=async(material:ShaderMaterial)=>{
      const timer=new GpuTimer(gl),samples:number[]=[]
      try{
        for(let i=0;i<6;i++){render(material);await new Promise(r=>setTimeout(r,0))}
        for(let i=0;i<32;i++){timer.measure(()=>render(material));await new Promise(r=>setTimeout(r,0));samples.push(...timer.poll())}
        const deadline=performance.now()+30000
        while(timer.pendingCount){await new Promise(r=>setTimeout(r,16));samples.push(...timer.poll());if(performance.now()>deadline)throw new Error('GPU timer timeout')}
        if(samples.length!==32)throw new Error('Incomplete timings')
        return {summary:stats(samples),samples}
      }finally{timer.dispose()}
    }
    const baseline=make(source);render(baseline)
    const reference=[read(output),read(output,1)],depthBefore=read(targets[0])
    const compare=(pixels:Float32Array,expected:Float32Array)=>{
      const bits=new Uint32Array(pixels.buffer),ebits=new Uint32Array(expected.buffer)
      let differentBits=0,maxError=0,error=0,signal=0
      for(let i=0;i<pixels.length;i++){if(bits[i]!==ebits[i])differentBits++;const delta=Math.abs(pixels[i]-expected[i]);maxError=Math.max(maxError,delta);error+=delta;signal+=Math.abs(expected[i])}
      return {differentBits,maxError,relativeError:error/Math.max(signal,1e-20),signal}
    }
    if(!reference[0].some(v=>v>0)||!reference[1].some(v=>v!==0))throw new Error('Empty color or representative-position fixture')
    const rows=[]
    for(const [name,material]of [['baseline',baseline],...candidateSources(source).map(([n,s])=>[n,make(s)]),['baselineRepeat',baseline]]as [string,ShaderMaterial][]){
      render(material);const image={color:compare(read(output),reference[0]),position:compare(read(output,1),reference[1])},timing=await measure(material)
      rows.push({name,image,...timing});console.info('NEBULA_MARCH',actorId,name,JSON.stringify({image,summary:timing.summary}))
    }
    if(read(targets[0]).some((v,i)=>v!==depthBefore[i])||gl.getError())throw new Error('Depth drift or GL error')
    const values:any={};for(const[name,u]of Object.entries(uniforms)as any)values[name]=u.value?.isTexture?{texture:true,width:u.value.image.width,height:u.value.image.height,depth:u.value.image.depth}:u.value?.toArray?u.value.toArray():u.value
    return {actorId,width,height,snapshot,actualTarget,defines,uniforms:values,rows,sceneDepthUnchanged:true}
  }finally{
    renderer.render=draw;materials.forEach(m=>m.dispose());targets.forEach(t=>t.dispose());copyMesh.geometry.dispose();copyMaterial.dispose()
    renderer.setRenderTarget(savedTarget);renderer.setClearColor(savedColor,savedAlpha);renderer.autoClear=savedAuto;engine.start()
  }
}

