import { createServer } from 'vite'
import { chromium } from '@playwright/test'
import { writeFile } from 'node:fs/promises'
Object.assign(process.env, { VITE_FS_DRIVER: 's3', VITE_S3_URL: 'https://storage.yandexcloud.net',
  VITE_FILE_BUCKET: 'textures', VITE_SHOW_STATS_PANEL: 'false', VITE_SKY_SOURCE: 'gaia' })
const mode = 'split'
const outputPath = 'benchmark-results/heavy-scenes/nebula-view-bound-diagnosis-2026-10-27.json'
const report = { baselineCommit: 'eec46ee69a47ef65a5de01c54f677b81c201083f', mode, startedAt: new Date().toISOString(), rows: [], errors: [], warnings: [], assetFailures: [], abortedRequests: [], outcome: 'failed' }
let server, browser
try {
  server = await createServer({ server: { host: '127.0.0.1', port: 8094, strictPort: true, hmr: false } }); await server.listen()
  browser = await chromium.launch({ channel: 'chrome', headless: true })
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 })
  page.on('pageerror', e => report.errors.push(e.stack || e.message))
  page.on('console', m => { if (m.type() === 'error') report.errors.push(m.text()); if (m.type() === 'warning') report.warnings.push(m.text()); if (m.text().startsWith('NEBULA_MARCH')) console.log(m.text()) })
  page.on('response', r => { if (r.status() >= 400) report.assetFailures.push(`${r.status()} ${r.url()}`) })
  page.on('requestfailed', r => { (/ERR_ABORTED/.test(r.failure()?.errorText ?? '') ? report.abortedRequests : report.assetFailures).push(`${r.failure()?.errorText} ${r.url()}`) })
  await page.goto('http://127.0.0.1:8094/'); await page.getByRole('button', { name: /^Run / }).first().waitFor()
  for (const [id, belt, nebula] of [[13, 135, 136], [12, 127, 118]]) {
    console.log('Starting', id)
    await page.evaluate(async id => Promise.race([(await import('/tests/browser/scenarioSoak.browser.ts')).selectScenario(id),
      new Promise((_, reject) => setTimeout(() => reject(new Error('Startup timeout')), 180000))]), id)
    const view = await page.evaluate(async id => (await import('/benchmark-results/heavy-scenes/profile.browser.ts')).setView(id, 'belt'), belt)
    await page.waitForTimeout(5000)
    const row = await page.evaluate(async ({ id, mode }) => (await import('/benchmark-results/heavy-scenes/nebula-view-bound-diagnosis-2026-10-27.browser.ts')).diagnose(id, mode), { id: nebula, mode })
    if (/SwiftShader|llvmpipe|software/i.test(row.snapshot.renderer)) throw new Error('Software renderer')
    report.rows.push({ id, view, ...row })
    console.log('Completed scene', id)
    await writeFile(outputPath, JSON.stringify(report, null, 2))
    await page.evaluate(async () => (await import('/tests/browser/scenarioSoak.browser.ts')).returnToMenu())
    if (report.errors.length || report.warnings.length || report.assetFailures.length) throw new Error('Browser or asset errors')
  }
  report.outcome = 'completed'
} catch (e) { report.failure = e.stack || e.message; console.error(e); process.exitCode = 1 }
finally {
  report.finishedAt = new Date().toISOString()
  await writeFile(outputPath, JSON.stringify(report, null, 2))
  await browser?.close(); await server?.close()
}

