import { getInitializedSimulationRuntime } from '/src/ui/runtime/simulationRuntime'
import { Tokens } from '/src/core/providers/tokens'
import { InstanceVisibility } from '/src/core/renderables/DetailedRingStreamingSystem/InstanceVisibility'
import { Vector3 } from 'three'
import { InstancePool } from '/src/core/renderables/DetailedRingStreamingSystem/InstancePool'
import { SectorGrid } from '/src/core/renderables/DetailedRingStreamingSystem/SectorGrid'
import { AsteroidGenerator } from '/src/core/renderables/DetailedRingStreamingSystem/AsteroidGenerator'
import { SectorManager } from '/src/core/renderables/DetailedRingStreamingSystem/SectorManager'
import { profile } from './shape-profile.browser'

const stats = (values: number[]) => {
  const sorted = values.slice().sort((a, b) => a - b)
  return { count: values.length, p50: sorted[Math.ceil(values.length * .5) - 1], p95: sorted[Math.ceil(values.length * .95) - 1], max: sorted.at(-1), mean: values.reduce((a, b) => a + b, 0) / values.length }
}
export async function diagnoseMotionCpu(mode = 'passes', motion = true) {
  const c = getInitializedSimulationRuntime()!.container, engine = c.get(Tokens.Engine), camera = c.get(Tokens.Camera)
  const position = camera.position.clone(), orientation = camera.quaternion.clone(), originalFrame = engine.renderFrame
  const direction = new Vector3(1, 0, 0).applyQuaternion(orientation)
  const originals = { update: InstanceVisibility.prototype.update, updateImpostors: InstanceVisibility.prototype.updateImpostors }
  let frame = 0, measuredFrame: number | null = null, excludedVisibilityUpdates = 0
  const visibilityUpdates: any[] = []
  const detail:Record<string,number[]>=Object.fromEntries(['copy','copyCalls','copyBytes','sectors','commit','grid','fades','allocation','generate','grouped'].map(key=>[key,Array(96).fill(0)]))
  const instances=new Set<any>(),undo:(()=>void)[]=[]
  const wrap=(proto:any,key:string,label:string)=>{
    const old=proto[key]
    proto[key]=function(...args:any[]){
      if(measuredFrame===null)return old.apply(this,args)
      const copying=label==='copy'&&(args[2]||this.versions.get(args[0])!==args[0].version)
      const started=performance.now(),result=old.apply(this,args)
      detail[label][measuredFrame]+=performance.now()-started
      if(copying){detail.copyCalls[measuredFrame]++;detail.copyBytes[measuredFrame]+=this.visibleCount*args[0].itemSize*args[0].array.BYTES_PER_ELEMENT}
      if(label==='copy')instances.add(this)
      return result
    }
    undo.push(()=>proto[key]=old)
  }
  wrap(InstanceVisibility.prototype,'copyVisible','copy')
  wrap(SectorManager.prototype,'update','sectors')
  wrap(InstancePool.prototype,'commitUpdates','commit')
  wrap(SectorGrid.prototype,'getSectorsInRange','grid')
  wrap(SectorManager.prototype,'updateFades','fades')
  wrap(SectorManager.prototype,'allocateForLOD','allocation')
  wrap(AsteroidGenerator.prototype,'generateMatrices','generate')
  wrap(AsteroidGenerator.prototype,'generateMatricesGrouped','grouped')
  for (const method of ['update', 'updateImpostors'] as const) {
    const original = originals[method] as any
    InstanceVisibility.prototype[method] = function (...args: any[]) {
      if (measuredFrame === null) { excludedVisibilityUpdates++; return original.apply(this, args) }
      const start = performance.now(), result = original.apply(this, args), ms = performance.now() - start
      const mesh = (this as any).mesh
      visibilityUpdates.push({ frame: measuredFrame, group: method === 'updateImpostors' ? 'L1' : /AsteroidPool_L0/.test(mesh.name) ? 'L0' : 'Near', mesh: mesh.name, ms, submitted: mesh.count, source: args[1] })
      return result
    }
  }
  engine.renderFrame = function () {
    if (frame >= 96) return originalFrame.call(this)
    measuredFrame = frame++
    const progress = measuredFrame / 95
    if(motion) camera.position.copy(position).addScaledVector(direction, progress * 2)
    camera.quaternion.copy(orientation); if(motion) camera.rotateY(progress * Math.PI * 2); camera.updateMatrixWorld(true)
    try { return originalFrame.call(this) } finally { measuredFrame = null }
  }
  try {
    const result = await profile(96, mode, false)
    if (frame !== 96 || new Set(visibilityUpdates.map(update => update.frame)).size !== 96) throw new Error('Incomplete CPU motion window')
    const perFrame: Record<string, number[]> = Object.fromEntries(['Near', 'L0', 'L1', 'other', 'total'].map(key => [key, Array(96).fill(0)]))
    if (mode === 'draws') for (const [key, samples] of Object.entries(result.gpu)) {
      const frames = result.drawFrameIndices[key]
      if (frames.length !== samples.length) throw new Error('Draw samples lost frame correspondence')
      const group = key.match(/AsteroidPool_(Near|L0|L1)/)?.[1] ?? 'other'
      samples.forEach((ms, i) => { perFrame[group][frames[i]] += ms; perFrame.total[frames[i]] += ms })
    }
    const cpuPerFrame: Record<string, number[]> = Object.fromEntries(['Near', 'L0', 'L1', 'total'].map(key => [key, Array(96).fill(0)]))
    for (const update of visibilityUpdates) {
      if (update.frame >= 96) throw new Error('Unexpected visibility update frame')
      cpuPerFrame[update.group][update.frame] += update.ms; cpuPerFrame.total[update.frame] += update.ms
    }
    const compaction=Array.from(instances).filter(v=>v.visibleCount>0).map(v=>{
      const lengths:number[]=[];let start=0
      for(let i=1;i<=v.visibleCount;i++)if(i===v.visibleCount||v.slots[i]!==v.slots[i-1]+1){lengths.push(i-start);start=i}
      return {mesh:v.mesh.name,visible:v.visibleCount,runs:lengths.length,singletons:lengths.filter(n=>n===1).length,longRunSlots:lengths.filter(n=>n>=4).reduce((a,b)=>a+b,0),maxRun:Math.max(...lengths)}
    })
    return { ...result, motion,detail,detailSummary:Object.fromEntries(Object.entries(detail).map(([k,v])=>[k,stats(v)])),compaction, perFrame, groups: Object.fromEntries(Object.entries(perFrame).map(([key, values]) => [key, stats(values)])),
      visibilityUpdates, excludedVisibilityUpdates, cpuPerFrame, visibilityCpu: Object.fromEntries(Object.entries(cpuPerFrame).map(([key, values]) => [key, stats(values)])),
      caveat: '96 real frames; motion=true uses~3990km translation and360-degree camera turn, otherwise stationary. CPU copy/sector/commit wrappers add instrumentation overhead; final run-length snapshot is descriptive, not a paired timing input. Draw mode sums native per-draw GPU queries in RenderPass, excluding volumes/postprocess; frame mode measures full renderFrame separately. Query overhead present. CPU visibility uses browser timer precision. No paired baseline motion or whole-frame speedup claim.' }
  } finally {
    for(const restore of undo.reverse())restore()
    InstanceVisibility.prototype.update = originals.update; InstanceVisibility.prototype.updateImpostors = originals.updateImpostors; engine.renderFrame = originalFrame
    camera.position.copy(position); camera.quaternion.copy(orientation)
  }
}

